package org.joda.time;

import java.io.*;
import java.io.IOException;
import java.io.ObjectInputStream;
import java.io.ObjectOutputStream;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.Locale;
import org.joda.convert.FromString;
import org.joda.convert.ToString;
import org.joda.time.base.BaseDateTime;
import org.joda.time.chrono.ISOChronology;
import org.joda.time.field.AbstractReadableInstantFieldProperty;
import org.joda.time.field.FieldUtils;
import org.joda.time.format.DateTimeFormatter;
import org.joda.time.format.ISODateTimeFormat;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class MutableDateTime_addYears_TriageGen1Test {

    @Test
    public void testAddYears_Positive() {
        // Test adding positive years
        MutableDateTime dt = new MutableDateTime(2020, 1, 1, 0, 0, 0, 0);
        dt.addYears(5);
        assertEquals(2025, dt.getYear());
        assertEquals(1, dt.getMonthOfYear());
        assertEquals(1, dt.getDayOfMonth());
    }

    @Test
    public void testAddYears_Negative() {
        // Test adding negative years (subtracting)
        MutableDateTime dt = new MutableDateTime(2020, 1, 1, 0, 0, 0, 0);
        dt.addYears(-5);
        assertEquals(2015, dt.getYear());
        assertEquals(1, dt.getMonthOfYear());
        assertEquals(1, dt.getDayOfMonth());
    }

    @Test
    public void testAddYears_Zero() {
        // Test adding zero years
        MutableDateTime dt = new MutableDateTime(2020, 5, 15, 10, 30, 0, 0);
        dt.addYears(0);
        assertEquals(2020, dt.getYear());
        assertEquals(5, dt.getMonthOfYear());
        assertEquals(15, dt.getDayOfMonth());
    }

    @Test
    public void testAddYears_LeapYearToNonLeapYear() {
        // Test leap year edge case: Feb 29th + 1 year should be Feb 28th
        MutableDateTime dt = new MutableDateTime(2020, 2, 29, 0, 0, 0, 0);
        dt.addYears(1);
        assertEquals(2021, dt.getYear());
        assertEquals(2, dt.getMonthOfYear());
        assertEquals(28, dt.getDayOfMonth());
    }

    @Test
    public void testAddYears_NonLeapYearToLeapYear() {
        // Test non-leap year to leap year: Feb 28th + 1 year should be Feb 28th
        MutableDateTime dt = new MutableDateTime(2021, 2, 28, 0, 0, 0, 0);
        dt.addYears(1);
        assertEquals(2022, dt.getYear());
        assertEquals(2, dt.getMonthOfYear());
        assertEquals(28, dt.getDayOfMonth());
    }

    @Test
    public void testAddYears_LargeValue() {
        // Test very large year addition
        MutableDateTime dt = new MutableDateTime(1, 1, 1, 0, 0, 0, 0);
        dt.addYears(1000);
        assertEquals(1001, dt.getYear());
    }

    @Test
    public void testAddYears_WithTimeComponent() {
        // Ensure time components are preserved
        MutableDateTime dt = new MutableDateTime(2000, 12, 31, 23, 59, 59, 999);
        dt.addYears(2);
        assertEquals(2002, dt.getYear());
        assertEquals(12, dt.getMonthOfYear());
        assertEquals(31, dt.getDayOfMonth());
        assertEquals(23, dt.getHourOfDay());
        assertEquals(59, dt.getMinuteOfHour());
        assertEquals(59, dt.getSecondOfMinute());
        assertEquals(999, dt.getMillisOfSecond());
    }
}
